delete from ems_report_station_hour
where tenant_id = #{tenantId}

    and company_id = #{companyId}


    and station_id = #{stationId}

and stat_time  >=  #{startTime}
and stat_time  <=  #{endTime}

mapper.insert:
insert into ems_report_station_hour (tenant_id, company_id, station_id, stat_time, generation_kwh, charge_kwh, discharge_kwh, consumption_kwh, grid_import_kwh, grid_export_kwh, revenue_amount, feed_in_revenue, self_use_saving, storage_arbitrage_revenue, purchase_cost, revenue_quality_reason, equivalent_hours, co2_reduction_kg, standard_coal_kg, equivalent_trees, data_quality, quality_reason, create_time, update_time) with raw_metrics as ( select h.tenant_id, h.company_id, h.station_id, as stat_time, h.bucket_time, concat(ifnull(nullif(h.edge_id, ''), concat('device:', h.device_id)), '/', ifnull(nullif(h.component_id, ''), concat('device:', h.device_id))) as source_component_key, case when h.metric_key in ('generation', 'generationKwh', 'generation_kwh') then 'GENERATION' when h.metric_key in ('gridImport', 'gridImportKwh', 'grid_import_kwh', 'importEnergyKwh') then 'GRID_IMPORT' when h.metric_key in ('gridExport', 'gridExportKwh', 'grid_export_kwh', 'exportEnergyKwh') then 'GRID_EXPORT' when h.metric_key in ('consumption', 'consumptionKwh', 'consumption_kwh', 'loadEnergyKwh') then 'CONSUMPTION' when h.metric_key in ('charge', 'chargeKwh', 'charge_kwh', 'chargeEnergyKwh') and ifnull(h.metric_value, 0) <> 0 then 'CHARGE' when h.metric_key in ('discharge', 'dischargeKwh', 'discharge_kwh', 'dischargeEnergyKwh') and ifnull(h.metric_value, 0) <> 0 then 'DISCHARGE' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role = 'GRID_METER' or (d.device_type = 'METER' and h.component_id in ('meter0', 'grid0'))) and ifnull(h.metric_value, 0) > 0 and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality in ('GOOD', 'PARTIAL') and e.metric_key in ('gridImport', 'gridImportKwh', 'grid_import_kwh', 'importEnergyKwh') and ifnull(e.metric_value, 0) <> 0 ) then 'GRID_IMPORT' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role = 'GRID_METER' or (d.device_type = 'METER' and h.component_id in ('meter0', 'grid0'))) and ifnull(h.metric_value, 0) < 0 and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality in ('GOOD', 'PARTIAL') and e.metric_key in ('gridExport', 'gridExportKwh', 'grid_export_kwh', 'exportEnergyKwh') and ifnull(e.metric_value, 0) <> 0 ) then 'GRID_EXPORT' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('PRODUCTION_METER', 'INVERTER') or d.device_type = 'INVERTER') then 'GENERATION' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and h.source_role = 'CONSUMPTION_METER' then 'CONSUMPTION' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) and ifnull(h.metric_value, 0) < 0 then 'CHARGE' when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) and ifnull(h.metric_value, 0) > 0 then 'DISCHARGE' when h.metric_key in ('chargePower', 'chargePowerKw', 'charge_power_kw') then 'CHARGE' when h.metric_key in ('dischargePower', 'dischargePowerKw', 'discharge_power_kw') then 'DISCHARGE' else null end as metric_group, case when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) then abs(ifnull(h.metric_value, 0)) / 12 when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power', 'chargePower', 'chargePowerKw', 'charge_power_kw', 'dischargePower', 'dischargePowerKw', 'discharge_power_kw') then abs(ifnull(h.metric_value, 0)) / 12 else ifnull(h.metric_value, 0) end as metric_value, case when h.source_priority is not null then h.source_priority when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) then 30 when h.source_role = 'PRODUCTION_METER' then 10 when h.source_role = 'GRID_METER' then 10 when h.source_role = 'PCS' then 10 when h.source_role = 'INVERTER' then 20 when h.source_role = 'ESS' then 20 when h.source_role = 'SUM' then 30 when d.device_type = 'METER' then 10 when d.device_type = 'PCS' then 10 when d.device_type = 'INVERTER' then 20 when d.device_type = 'ESS' then 20 else 100 end as source_rank, h.quality from ems_metric_history_5min h inner join ems_device d on d.id = h.device_id and d.del_flag = '0' where h.tenant_id = #{tenantId}
and h.company_id = #{companyId}
and h.station_id = #{stationId}
and h.bucket_time >= #{startTime} and h.bucket_time <= #{endTime} ), source_metrics as ( select tenant_id, company_id, station_id, stat_time, bucket_time, source_component_key, metric_group, source_rank, max(case when quality in ('GOOD', 'PARTIAL') then metric_value else null end) as metric_value, case when sum(case when quality = 'BAD' then 1 else 0 end) > 0 then 'BAD' when sum(case when quality = 'MISSING' then 1 else 0 end) > 0 then 'MISSING' when sum(case when quality = 'PARTIAL' then 1 else 0 end) > 0 then 'PARTIAL' else 'GOOD' end as data_quality, count(1) as source_count from raw_metrics where metric_group is not null group by tenant_id, company_id, station_id, stat_time, bucket_time, source_component_key, metric_group, source_rank ), preferred_source_rank as ( select tenant_id, station_id, stat_time, bucket_time, case when metric_group = 'GENERATION' then '__station_generation__' else source_component_key end as source_dedupe_key, metric_group, min(source_rank) as source_rank from source_metrics group by tenant_id, station_id, stat_time, bucket_time, case when metric_group = 'GENERATION' then '__station_generation__' else source_component_key end, metric_group ), preferred_metrics as ( select m.* from source_metrics m inner join preferred_source_rank p on p.tenant_id = m.tenant_id and p.station_id = m.station_id and p.stat_time = m.stat_time and p.bucket_time = m.bucket_time and p.metric_group = m.metric_group and p.source_dedupe_key = case when m.metric_group = 'GENERATION' then '__station_generation__' else m.source_component_key end and p.source_rank = m.source_rank ) select tenant_id, company_id, station_id, stat_time, sum(case when metric_group = 'GENERATION' then ifnull(metric_value, 0) else 0 end) as generation_kwh, sum(case when metric_group = 'CHARGE' then ifnull(metric_value, 0) else 0 end) as charge_kwh, sum(case when metric_group = 'DISCHARGE' then ifnull(metric_value, 0) else 0 end) as discharge_kwh, sum(case when metric_group = 'CONSUMPTION' then ifnull(metric_value, 0) else 0 end) as consumption_kwh, sum(case when metric_group = 'GRID_IMPORT' then ifnull(metric_value, 0) else 0 end) as grid_import_kwh, sum(case when metric_group = 'GRID_EXPORT' then ifnull(metric_value, 0) else 0 end) as grid_export_kwh, 0 as revenue_amount, 0 as feed_in_revenue, 0 as self_use_saving, 0 as storage_arbitrage_revenue, 0 as purchase_cost, null as revenue_quality_reason, 0 as equivalent_hours, 0 as co2_reduction_kg, 0 as standard_coal_kg, 0 as equivalent_trees, case when sum(case when data_quality = 'BAD' then 1 else 0 end) > 0 then 'BAD' when sum(case when data_quality = 'MISSING' then 1 else 0 end) > 0 then 'MISSING' when sum(case when data_quality = 'PARTIAL' then 1 else 0 end) > 0 then 'PARTIAL' else 'GOOD' end as data_quality, concat('按来源优先级聚合自', sum(source_count), '条5分钟指标记录') as quality_reason, now(), now() from preferred_metrics group by tenant_id, company_id, station_id, stat_time on duplicate key update company_id = values(company_id), generation_kwh = values(generation_kwh), charge_kwh = values(charge_kwh), discharge_kwh = values(discharge_kwh), consumption_kwh = values(consumption_kwh), grid_import_kwh = values(grid_import_kwh), grid_export_kwh = values(grid_export_kwh), data_quality = values(data_quality), quality_reason = values(quality_reason), update_time = now()

