mapper.insert:
insert into ems_report_device_hour (tenant_id, company_id, station_id, device_id, device_type, stat_time, generation_kwh, charge_kwh, discharge_kwh, runtime_hours, peak_power_kw, avg_soc, avg_soh, alarm_count, data_quality, quality_reason, create_time, update_time) select h.tenant_id, h.company_id, h.station_id, h.device_id, d.device_type, as stat_time, sum(case when h.quality in ('GOOD', 'PARTIAL') and h.metric_key in ('generation', 'generationKwh', 'generation_kwh') then ifnull(h.metric_value, 0) when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and h.quality = 'GOOD' and (h.source_role in ('PRODUCTION_METER', 'INVERTER') or d.device_type = 'INVERTER') and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality in ('GOOD', 'PARTIAL') and e.metric_key in ('generation', 'generationKwh', 'generation_kwh') and ifnull(e.metric_value, 0) <> 0 ) then ifnull(h.metric_value, 0) / 12 else 0 end) as generation_kwh, sum(case when h.quality in ('GOOD', 'PARTIAL') and h.metric_key in ('charge', 'chargeKwh', 'charge_kwh', 'chargeEnergyKwh') then ifnull(h.metric_value, 0) when h.quality in ('GOOD', 'PARTIAL') and d.device_type = 'CHARGER' and h.metric_key in ('consumption', 'consumptionKwh', 'consumption_kwh', 'evcsChargeKwh') then ifnull(h.metric_value, 0) when h.quality = 'GOOD' and h.metric_key in ('chargePower', 'chargePowerKw', 'charge_power_kw') then abs(ifnull(h.metric_value, 0)) / 12 when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and h.quality = 'GOOD' and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) and ifnull(h.metric_value, 0) < 0 and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality in ('GOOD', 'PARTIAL') and e.metric_key in ('charge', 'chargeKwh', 'charge_kwh', 'chargeEnergyKwh', 'chargePower', 'chargePowerKw', 'charge_power_kw') and ifnull(e.metric_value, 0) <> 0 ) then abs(ifnull(h.metric_value, 0)) / 12 else 0 end) as charge_kwh, sum(case when h.quality in ('GOOD', 'PARTIAL') and h.metric_key in ('discharge', 'dischargeKwh', 'discharge_kwh', 'dischargeEnergyKwh') then ifnull(h.metric_value, 0) when h.quality = 'GOOD' and h.metric_key in ('dischargePower', 'dischargePowerKw', 'discharge_power_kw') then abs(ifnull(h.metric_value, 0)) / 12 when h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and h.quality = 'GOOD' and (h.source_role in ('ESS', 'PCS') or d.device_type in ('ESS', 'STORAGE', 'PCS')) and ifnull(h.metric_value, 0) > 0 and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality in ('GOOD', 'PARTIAL') and e.metric_key in ('discharge', 'dischargeKwh', 'discharge_kwh', 'dischargeEnergyKwh', 'dischargePower', 'dischargePowerKw', 'discharge_power_kw') and ifnull(e.metric_value, 0) <> 0 ) then abs(ifnull(h.metric_value, 0)) / 12 else 0 end) as discharge_kwh, sum(case when h.quality = 'GOOD' and h.metric_key in ('runtime', 'runtimeHours', 'runtime_hours') then ifnull(h.metric_value, 0) when h.quality = 'GOOD' and h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') and (h.source_role in ('PRODUCTION_METER', 'INVERTER') or d.device_type = 'INVERTER') and ifnull(h.metric_value, 0) > 0.01 and not exists ( select 1 from ems_metric_history_5min e where e.tenant_id = h.tenant_id and e.device_id = h.device_id and e.bucket_time = h.bucket_time and e.quality = 'GOOD' and e.metric_key in ('runtime', 'runtimeHours', 'runtime_hours') and ifnull(e.metric_value, 0) <> 0 ) then 1 / 12 else 0 end) as runtime_hours, max(case when h.quality = 'GOOD' and h.metric_key in ('activePower', 'activePowerKw', 'active_power_kw', 'power') then ifnull(h.metric_value, 0) else 0 end) as peak_power_kw, avg(case when h.quality = 'GOOD' and h.metric_key in ('soc', 'avgSoc') then h.metric_value else null end) as avg_soc, avg(case when h.quality = 'GOOD' and h.metric_key in ('soh', 'avgSoh') then h.metric_value else null end) as avg_soh, sum(case when h.quality = 'GOOD' and h.metric_key in ('alarmCount', 'alarm_count', 'alarm') then ifnull(h.metric_value, 0) else 0 end) as alarm_count, case when sum(case when h.quality = 'BAD' then 1 else 0 end) > 0 then 'BAD' when sum(case when h.quality = 'MISSING' then 1 else 0 end) > 0 then 'MISSING' when sum(case when h.quality = 'PARTIAL' then 1 else 0 end) > 0 then 'PARTIAL' else 'GOOD' end as data_quality, concat('聚合自', count(1), '条5分钟指标记录') as quality_reason, now(), now() from ems_metric_history_5min h inner join ems_device d on d.id = h.device_id and d.del_flag = '0' where h.tenant_id = #{tenantId}
and h.company_id = #{companyId}
and h.station_id = #{stationId}
and d.device_type = #{deviceType}
and h.bucket_time >= #{startTime} and h.bucket_time <= #{endTime} group by h.tenant_id, h.company_id, h.station_id, h.device_id, d.device_type, on duplicate key update company_id = values(company_id), station_id = values(station_id), device_type = values(device_type), generation_kwh = values(generation_kwh), charge_kwh = values(charge_kwh), discharge_kwh = values(discharge_kwh), runtime_hours = values(runtime_hours), peak_power_kw = values(peak_power_kw), avg_soc = values(avg_soc), avg_soh = values(avg_soh), alarm_count = values(alarm_count), data_quality = values(data_quality), quality_reason = values(quality_reason), update_time = now()

