mapper.insert:
insert into (tenant_id, company_id, station_id, stat_time, generation_kwh, charge_kwh, discharge_kwh, consumption_kwh, grid_import_kwh, grid_export_kwh, revenue_amount, feed_in_revenue, self_use_saving, storage_arbitrage_revenue, purchase_cost, revenue_quality_reason, equivalent_hours, co2_reduction_kg, standard_coal_kg, equivalent_trees, data_quality, quality_reason, create_time, update_time) select tenant_id, company_id, station_id, as stat_time, sum(ifnull(generation_kwh, 0)) as generation_kwh, sum(ifnull(charge_kwh, 0)) as charge_kwh, sum(ifnull(discharge_kwh, 0)) as discharge_kwh, sum(ifnull(consumption_kwh, 0)) as consumption_kwh, sum(ifnull(grid_import_kwh, 0)) as grid_import_kwh, sum(ifnull(grid_export_kwh, 0)) as grid_export_kwh, sum(ifnull(revenue_amount, 0)) as revenue_amount, sum(ifnull(feed_in_revenue, 0)) as feed_in_revenue, sum(ifnull(self_use_saving, 0)) as self_use_saving, sum(ifnull(storage_arbitrage_revenue, 0)) as storage_arbitrage_revenue, sum(ifnull(purchase_cost, 0)) as purchase_cost, group_concat(distinct revenue_quality_reason order by revenue_quality_reason separator ';') as revenue_quality_reason, sum(ifnull(equivalent_hours, 0)) as equivalent_hours, sum(ifnull(co2_reduction_kg, 0)) as co2_reduction_kg, sum(ifnull(standard_coal_kg, 0)) as standard_coal_kg, sum(ifnull(equivalent_trees, 0)) as equivalent_trees, as data_quality, concat('聚合自', count(1), '条源记录') as quality_reason, now(), now() from where tenant_id = #{tenantId}
and company_id = #{companyId}
and station_id = #{stationId}
and stat_time >= #{startTime} and stat_time <= #{endTime} group by tenant_id, company_id, station_id, on duplicate key update company_id = values(company_id), generation_kwh = values(generation_kwh), charge_kwh = values(charge_kwh), discharge_kwh = values(discharge_kwh), consumption_kwh = values(consumption_kwh), grid_import_kwh = values(grid_import_kwh), grid_export_kwh = values(grid_export_kwh), revenue_amount = values(revenue_amount), feed_in_revenue = values(feed_in_revenue), self_use_saving = values(self_use_saving), storage_arbitrage_revenue = values(storage_arbitrage_revenue), purchase_cost = values(purchase_cost), revenue_quality_reason = values(revenue_quality_reason), equivalent_hours = values(equivalent_hours), co2_reduction_kg = values(co2_reduction_kg), standard_coal_kg = values(standard_coal_kg), equivalent_trees = values(equivalent_trees), data_quality = values(data_quality), quality_reason = values(quality_reason), update_time = now()

