insert into (tenant_id, company_id, station_id, device_id, device_type, stat_time, generation_kwh, charge_kwh, discharge_kwh, runtime_hours, peak_power_kw, avg_soc, avg_soh, alarm_count, data_quality, quality_reason, create_time, update_time) select tenant_id, company_id, station_id, device_id, device_type, as stat_time, sum(ifnull(generation_kwh, 0)) as generation_kwh, sum(ifnull(charge_kwh, 0)) as charge_kwh, sum(ifnull(discharge_kwh, 0)) as discharge_kwh, sum(ifnull(runtime_hours, 0)) as runtime_hours, max(ifnull(peak_power_kw, 0)) as peak_power_kw, avg(avg_soc) as avg_soc, avg(avg_soh) as avg_soh, sum(ifnull(alarm_count, 0)) as alarm_count, as data_quality, concat('聚合自', count(1), '条源记录') as quality_reason, now(), now() from where tenant_id = #{tenantId}
and company_id = #{companyId}
and station_id = #{stationId}
and device_type = #{deviceType}
and stat_time >= #{startTime} and stat_time <= #{endTime} group by tenant_id, company_id, station_id, device_id, device_type, on duplicate key update company_id = values(company_id), station_id = values(station_id), device_type = values(device_type), generation_kwh = values(generation_kwh), charge_kwh = values(charge_kwh), discharge_kwh = values(discharge_kwh), runtime_hours = values(runtime_hours), peak_power_kw = values(peak_power_kw), avg_soc = values(avg_soc), avg_soh = values(avg_soh), alarm_count = values(alarm_count), data_quality = values(data_quality), quality_reason = values(quality_reason), update_time = now()
